/* Service worker – generated by scripts/build-sw.mjs from scripts/sw.template.js. Do not edit public/sw.js. */
/* global self, caches, fetch, Response, URL */

const VERSION = "__VERSION__";
const ROUTES = __ROUTES__;
const PRECACHE = `precache-${VERSION}`;
const RUNTIME = `runtime-${VERSION}`;
const IMAGES = "images-v1"; // image URLs are content-versioned, so this cache survives deploys
const IMAGE_LIMIT = 400;
const NAV_TIMEOUT_MS = 3500; // weak gym signal: fall back to the cached page instead of hanging
const EXTRA = ["/manifest.webmanifest", "/icons/icon-192.png", "/icons/icon-512.png", "/icons/apple-touch-icon.png"];

const ASSET_RE = /(?:\/_next\/)?static\/(?:chunks|css|media)\/[A-Za-z0-9_\-.~%/[\]()]+?\.(?:js|css|woff2?)/g;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      const assets = new Set(EXTRA);
      for (const route of ROUTES) {
        try {
          const res = await fetch(route, { cache: "no-store", credentials: "same-origin" });
          if (!res.ok || res.redirected) continue;
          const html = await res.clone().text();
          await cache.put(route, res);
          for (const m of html.matchAll(ASSET_RE)) {
            const p = m[0].startsWith("/_next/") ? m[0] : `/_next/${m[0]}`;
            assets.add(p);
          }
        } catch {
          // Offline during install: whatever was cached is still useful.
        }
      }
      await Promise.all(
        [...assets].map(async (url) => {
          if (await cache.match(url)) return;
          try {
            const res = await fetch(url, { credentials: "same-origin" });
            if (res.ok) await cache.put(url, res);
          } catch {
            /* skip */
          }
        }),
      );
    })(),
  );
  // No skipWaiting(): an open workout keeps running on the old version until all tabs are closed,
  // so a deploy can never swap chunks out from under an active session.
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([PRECACHE, RUNTIME, IMAGES]);
      for (const key of await caches.keys()) if (!keep.has(key)) await caches.delete(key);
      await self.clients.claim();
    })(),
  );
});

const cacheable = (res) => res && res.ok && res.type === "basic" && !res.redirected;

async function trim(cacheName, max) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - max; i++) await cache.delete(keys[i]);
}

async function fromCache(request, opts) {
  return (await caches.match(request, opts)) ?? undefined;
}

async function networkFirstPage(request) {
  const network = fetch(request).then(async (res) => {
    if (cacheable(res)) {
      const cache = await caches.open(RUNTIME);
      await cache.put(new URL(request.url).pathname, res.clone());
    }
    return res;
  });
  network.catch(() => {}); // handled below; avoid unhandled-rejection noise
  const timeout = new Promise((resolve) => setTimeout(() => resolve(undefined), NAV_TIMEOUT_MS));
  try {
    const res = await Promise.race([network, timeout]);
    if (res) return res;
  } catch {
    /* offline */
  }
  const path = new URL(request.url).pathname;
  const cached = (await fromCache(path)) ?? (await fromCache(request, { ignoreSearch: true }));
  if (cached) return cached;
  try {
    return await network; // slow but alive: keep waiting rather than failing
  } catch {
    return (
      (await fromCache("/")) ??
      new Response("<!doctype html><meta charset=utf-8><title>Offline</title><p style='font-family:system-ui;padding:2rem'>Du är offline.</p>", {
        headers: { "Content-Type": "text/html; charset=utf-8" },
      })
    );
  }
}

async function cacheFirst(request, cacheName, limit) {
  const hit = await fromCache(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (cacheable(res)) {
    const cache = await caches.open(cacheName);
    await cache.put(request, res.clone());
    if (limit) trim(cacheName, limit);
  }
  return res;
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME);
  const hit = await cache.match(request);
  const update = fetch(request)
    .then((res) => {
      if (cacheable(res)) cache.put(request, res.clone());
      return res;
    })
    .catch(() => undefined);
  return hit ?? (await update) ?? Response.error();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // Supabase etc. go straight to the network
  if (url.pathname === "/sw.js") return;

  // React Server Component payloads: network only. On failure Next.js falls back to a full
  // page navigation, which is then served from the page cache below.
  if (request.headers.get("RSC") === "1" || url.searchParams.has("_rsc")) return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirstPage(request));
  } else if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request, RUNTIME));
  } else if (url.pathname.startsWith("/images/opt/")) {
    event.respondWith(cacheFirst(request, IMAGES, IMAGE_LIMIT));
  } else {
    event.respondWith(staleWhileRevalidate(request));
  }
});
